    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []
        out, queue = [], deque([root])
        while queue:
            size = len(queue)
            for i in range(size):
                node = queue.popleft()
                if i == size - 1:
                    out.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
        return out

