  // JavaScript has no built-in heap, so keep the array sorted instead.
  const s = [...stones].sort((a, b) => a - b);
  while (s.length > 1) {
    const a = s.pop(), b = s.pop();
    if (a !== b) { s.push(a - b); s.sort((x, y) => x - y); }
  }
  return s.length ? s[0] : 0;
};

