var rob = function(nums) {
  const rob = (a) => {
    let take = 0, skip = 0;
    for (const x of a) {
      const nt = skip + x;
      skip = Math.max(take, skip);
      take = nt;
    }
    return Math.max(take, skip);
  };
  if (nums.length === 1) return nums[0];
  return Math.max(rob(nums.slice(0, -1)), rob(nums.slice(1)));
};

