    for (let j = 1; j <= word2.length; j++) {
      const sub = prev[j - 1] + (word1[i - 1] === word2[j - 1] ? 0 : 1);
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, sub));
    }
    prev = cur;
  }
  return prev[word2.length];
};

