                int a = st.back(); st.pop_back();
                if (t[0] == '+') st.push_back(a + b);
                else if (t[0] == '-') st.push_back(a - b);
                else if (t[0] == '*') st.push_back(a * b);
                else st.push_back(a / b); // C++ truncates toward zero
            } else {
                st.push_back(stoi(t));
            }
        }
        return st[0];
    }
};

