class Solution {
    public int evalRPN(String tokens) {
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        for (String t : tokens.trim().split("\\s+")) {
            if (t.length() == 1 && "+-*/".indexOf(t.charAt(0)) >= 0) {
                int b = st.pop(), a = st.pop();
                switch (t.charAt(0)) {
                    case '+': st.push(a + b); break;
                    case '-': st.push(a - b); break;
                    case '*': st.push(a * b); break;
                    default: st.push(a / b); // Java truncates toward zero
                }
            } else {
                st.push(Integer.parseInt(t));
            }
        }
        return st.pop();
    }
}

