class Solution {
public:
    int carFleet(int target, vector<int>& position, vector<int>& speed) {
        int n = position.size();
        vector<int> idx(n);
        for (int i = 0; i < n; i++) idx[i] = i;
        sort(idx.begin(), idx.end(), [&](int a, int b) { return position[a] > position[b]; });
        int fleets = 0;
        long long cd = 0, cs = 1; // distance and speed of the leading fleet
        for (int i : idx) {
            long long d = target - position[i], s = speed[i];
            if (d * cs > cd * s) { // arrives later than the fleet ahead -> new fleet
                fleets++;
                cd = d;
                cs = s;
            }
        }
        return fleets;
    }
};

