class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        // P - N = target and P + N = total  =>  P = (total + target) / 2 (subset-sum count)
        int total = 0;
        for (int x : nums) total += x;
        if (abs(target) > total || (total + target) % 2 != 0) return 0;
        int need = (total + target) / 2;
        vector<long long> dp(need + 1, 0);
        dp[0] = 1;
        for (int x : nums)
            for (int j = need; j >= x; j--) dp[j] += dp[j - x];
        return (int)dp[need];
    }
};

