        # P - N = target and P + N = total  =>  P = (total + target) / 2 (subset-sum count)
        total = sum(nums)
        if abs(target) > total or (total + target) % 2:
            return 0
        need = (total + target) // 2
        dp = [0] * (need + 1)
        dp[0] = 1
        for x in nums:
            for j in range(need, x - 1, -1):
                dp[j] += dp[j - x]
        return dp[need]

