class Solution {
public:
    int deleteAndEarn(vector<int>& nums) {
        vector<int> points(*max_element(nums.begin(), nums.end()) + 1, 0);
        for (int x : nums) points[x] += x;
        // house robber over the value line
        int take = 0, skip = 0;
        for (int p : points) {
            int nt = skip + p;
            skip = max(take, skip);
            take = nt;
        }
        return max(take, skip);
    }
};

