class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int hold = INT_MIN / 2; // holding a share
        int sold = 0;           // just sold today (cooldown tomorrow)
        int rest = 0;           // free to buy
        for (int p : prices) {
            int nh = max(hold, rest - p);
            int ns = hold + p;
            rest = max(rest, sold);
            hold = nh;
            sold = ns;
        }
        return max(sold, rest);
    }
};

