  let prev = matrix[0].slice();
  const n = prev.length;
  for (let r = 1; r < matrix.length; r++) {
    const cur = new Array(n);
    for (let c = 0; c < n; c++) {
      let best = prev[c];
      if (c > 0) best = Math.min(best, prev[c - 1]);
      if (c < n - 1) best = Math.min(best, prev[c + 1]);
      cur[c] = matrix[r][c] + best;
    }
    prev = cur;
  }
