public:
    int numDistinct(string s, string t) {
        int m = t.size();
        vector<long long> dp(m + 1, 0); // dp[j] = ways to form t[0..j) from the prefix of s seen so far
        dp[0] = 1;
        for (char ch : s)
            for (int j = m; j >= 1; j--)
                if (t[j - 1] == ch) dp[j] += dp[j - 1];
        return (int)dp[m];
    }
};

