        for (int t : tasks) counts[t]++;
        int mx = *max_element(counts.begin(), counts.end());
        int numMax = count(counts.begin(), counts.end(), mx);
        // (mx - 1) full frames of n + 1 slots, plus the final row of max-count tasks
        return max((int)tasks.size(), (mx - 1) * (n + 1) + numMax);
    }
