/**
 * @param {ListNode} head
 * @return {number}
 */
var pairSum = function(head) {
  // reverse the second half, then pair it with the first half
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
  }
  let prev = null;
  while (slow) {
    const next = slow.next;
    slow.next = prev;
    prev = slow;
    slow = next;
  }
  let best = 0;
  for (let a = head, b = prev; b; a = a.next, b = b.next) best = Math.max(best, a.val + b.val);
  return best;
};

