  const stack = [];
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if ((i === 0 || j === 0 || i === m - 1 || j === n - 1) && board[i][j] === 1) {
        board[i][j] = 2;
        stack.push([i, j]);
      }
    }
  }
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  while (stack.length) {
    const [i, j] = stack.pop();
    for (const [di, dj] of dirs) {
      const a = i + di, b = j + dj;
      if (a >= 0 && a < m && b >= 0 && b < n && board[a][b] === 1) {
        board[a][b] = 2;
        stack.push([a, b]);
      }
    }
  }
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) board[i][j] = board[i][j] === 2 ? 1 : 0;
  return;
};

