    int maxSubarraySumCircular(vector<int>& nums) {
        long long total = 0, curMax = 0, curMin = 0;
        long long bestMax = nums[0], bestMin = nums[0];
        for (int x : nums) {
            total += x;
            curMax = max(curMax + x, (long long)x);
            bestMax = max(bestMax, curMax);
            curMin = min(curMin + x, (long long)x);
            bestMin = min(bestMin, curMin);
        }
        if (bestMax < 0) return (int)bestMax;
        return (int)max(bestMax, total - bestMin);
    }
};

