class Solution {
public:
    int minWindow(string s, string t) {
        unordered_map<char, int> need;
        for (char c : t) need[c]++;
        int missing = t.size(), best = 0, left = 0;
        for (int right = 0; right < (int)s.size(); right++) {
            char c = s[right];
            if (need[c] > 0) missing--;
            need[c]--;
            if (missing == 0) {
                while (need[s[left]] < 0) { need[s[left]]++; left++; }
                int len = right - left + 1;
                if (best == 0 || len < best) best = len;
                need[s[left]]++;
                missing++;
                left++;
            }
        }
        return best;
    }
};

